import { MessageCircle } from "lucide-react"

export default function WhatsAppButton() {
    // Número provisto en el blueprint (sin espacios ni símbolos +)
    const phoneNumber = "5491154581170"
    const message = encodeURIComponent("Hola Isabel, quiero saber más sobre el curso Reinventadas 5.0")

    const whatsappUrl = `https://wa.me/${phoneNumber}?text=${message}`

    return (
        <a
            href={whatsappUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="fixed bottom-6 right-6 z-50 bg-[#25D366] text-white p-4 rounded-full shadow-lg hover:shadow-xl hover:scale-110 transition-all duration-300 flex items-center justify-center group"
            aria-label="Contactar por WhatsApp"
        >
            <MessageCircle className="w-8 h-8" strokeWidth={2.5} />

            {/* Tooltip visible en desktop */}
            <span className="absolute right-full mr-4 bg-white text-brand-text px-4 py-2 rounded-lg text-sm font-medium shadow-md opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none whitespace-nowrap hidden md:block">
                ¿Tenés dudas? ¡Escribime!
            </span>

            {/* Punto de notificación sutil */}
            <span className="absolute -top-1 -right-1 flex w-4 h-4">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
                <span className="relative inline-flex rounded-full w-4 h-4 bg-red-500 border-2 border-[#25D366]"></span>
            </span>
        </a>
    )
}
